import 'package:cozy_life_adventure/game/day_night/day_night_cycle.dart';
import 'package:cozy_life_adventure/game/state/hud_snapshot.dart';
import 'package:cozy_life_adventure/game/state/inventory_snapshot.dart';
import 'package:cozy_life_adventure/game/state/runtime_game_state.dart';
import 'package:cozy_life_adventure/game/tutorial/tutorial_progress.dart';
import 'package:cozy_life_adventure/game/weather/weather_schedule.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../support/game_content_test_support.dart';

void main() {
  group('HudSnapshot', () {
    test('ignores coordinates when the displayed clock time is unchanged', () {
      final initial = RuntimeGameState.initial().copyWith(
        dayCycleProgress: 0.01,
      );
      final changedOnlyOutsideHud = initial.copyWith(
        player: initial.player.copyWith(x: 900, y: 700),
        dayCycleProgress: 0.0101,
      );

      final first = HudSnapshot.fromRuntimeState(
        initial,
        itemCatalog: testGameContent.items,
      );
      final second = HudSnapshot.fromRuntimeState(
        changedOnlyOutsideHud,
        itemCatalog: testGameContent.items,
      );

      expect(first, second);
      expect(first.hashCode, second.hashCode);
    });

    test('distinguishes every displayed value', () {
      const baseline = HudSnapshot(
        moonflowerCount: 0,
        npc01Affinity: 0,
        npc01LevelOneAffinity: 3,
        npc01LevelLabel: null,
        currentTutorialObjective: TutorialProgress.moveObjective,
        dayTime: '10:00 AM',
        dayNightPhase: DayNightPhase.day,
      );

      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 1,
            npc01Affinity: 0,
            npc01LevelOneAffinity: 3,
            npc01LevelLabel: null,
            currentTutorialObjective: TutorialProgress.moveObjective,
            dayTime: '10:00 AM',
            dayNightPhase: DayNightPhase.day,
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 0,
            npc01Affinity: 1,
            npc01LevelOneAffinity: 3,
            npc01LevelLabel: null,
            currentTutorialObjective: TutorialProgress.moveObjective,
            dayTime: '10:00 AM',
            dayNightPhase: DayNightPhase.day,
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 0,
            npc01Affinity: 0,
            npc01LevelOneAffinity: 3,
            npc01LevelLabel: null,
            currentTutorialObjective: TutorialProgress.moveObjective,
            dayTime: '10:01 AM',
            dayNightPhase: DayNightPhase.day,
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 0,
            npc01Affinity: 0,
            npc01LevelOneAffinity: 3,
            npc01LevelLabel: 'Acquaintance',
            currentTutorialObjective: TutorialProgress.moveObjective,
            dayTime: '10:00 AM',
            dayNightPhase: DayNightPhase.day,
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 0,
            npc01Affinity: 0,
            npc01LevelOneAffinity: 5,
            npc01LevelLabel: null,
            currentTutorialObjective: TutorialProgress.moveObjective,
            dayTime: '10:00 AM',
            dayNightPhase: DayNightPhase.day,
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          const HudSnapshot(
            moonflowerCount: 0,
            npc01Affinity: 0,
            npc01LevelOneAffinity: 3,
            npc01LevelLabel: null,
            currentTutorialObjective: TutorialProgress.reachMoonwoodObjective,
            dayTime: '10:00 AM',

    test(
      'compares full item maps by contents independent of insertion order',
      () {
        final first = InventorySnapshot(
          itemCatalog: testGameContent.items,
          itemCounts: const {'moonflower': 2, 'future-herb': 1},
        );
        final second = InventorySnapshot(
          itemCatalog: testGameContent.items,
          itemCounts: const {'future-herb': 1, 'moonflower': 2},
        );

        expect(first, second);
        expect(first.hashCode, second.hashCode);
      },
    );

    test('distinguishes any item count or item ID change', () {
      final baseline = InventorySnapshot(
        itemCatalog: testGameContent.items,
        itemCounts: const {'moonflower': 2, 'future-herb': 1},
      );

      expect(
        baseline,
        isNot(
          InventorySnapshot(
            itemCatalog: testGameContent.items,
            itemCounts: const {'moonflower': 3, 'future-herb': 1},
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          InventorySnapshot(
            itemCatalog: testGameContent.items,
            itemCounts: const {'moonflower': 2},
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          InventorySnapshot(
            itemCatalog: testGameContent.items,
            itemCounts: const {'moonflower': 2, 'other-herb': 1},
          ),
        ),
      );
      expect(
        baseline,
        isNot(
          InventorySnapshot(
            itemCatalog: testGameContent.items,
            itemCounts: const {'moonflower': 2, 'future-herb': 1},
            activeItemId: 'moonflower',
          ),
        ),
      );
    });

    test('defensively freezes the supplied item map', () {
      final mutableCounts = {'moonflower': 1};
      final snapshot = InventorySnapshot(
        itemCatalog: testGameContent.items,
        itemCounts: mutableCounts,
      );

      mutableCounts['moonflower'] = 9;

      expect(snapshot.itemCounts, const {'moonflower': 1});
      expect(
        () => snapshot.itemCounts['moonflower'] = 2,
        throwsUnsupportedError,
      );
    });
  });
}
